vulnerabilities.technicalAnalysis:
**Location 1:** `external/default.html` (line 1)
  Replace innerHTML with textContent to prevent HTML injection
  ```
  iFactor.getUrlArgument("language")&&document.getElementById("scLanguage")&&(document.getElementById("scLanguage").innerHTML=iFactor.getUrlArgument("language"));
  ```

  **Suggested Fix:**
```diff
- iFactor.getUrlArgument("language")&&document.getElementById("scLanguage")&&(document.getElementById("scLanguage").innerHTML=iFactor.getUrlArgument("language"));
+ iFactor.getUrlArgument("language")&&document.getElementById("scLanguage")&&(document.getElementById("scLanguage").textContent=iFactor.getUrlArgument("language"));
```

**Location 2:** `external/default.html` (line 1)
  Use decodeURIComponent in the URL parser to handle all encoded characters properly
  ```
  d[1].replace(/%20/g, " ").replace(/^\s+|\s+$/g, "")
  ```

  **Suggested Fix:**
```diff
+ iFactor.getUrlArguments = function() {
+     var a = {}, b = window.location.search, c = 0, d = null;
+     if (null != b && "" != b) {
+         for (b = b.substr(1, b.length), b = b.split("&"), c = 0; c < b.length; c++) {
+             anArg = b[c], d = anArg.split("=");
+             a[d[0].replace(/%20/g, " ").replace(/^\s+|\s+$/g, "").toLowerCase()] =
+               d[1].replace(/%20/g, " ").replace(/^\s+|\s+$/g, "");
+         }
+     }
+     return a;;
```

